SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷77·晋高祖纪·天福三年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5136a33bd66e49c58489b48336695f7b1236b9b/content/books/zizhi-tongjian/vol-281/year-0938/part-01/sources/library/jiuwudaishi-077-february/source.txt", "note": "《旧五代史》卷77·晋高祖纪·天福三年二月，段落 jiu-wudaishi-205deb4a7860-p001912；已核上下文及传主，纸本及异文待核。", "id": "94bc4b60-02a8-54e2-9097-76e46d6ceacf"}, {"title": "旧五代史·卷77·晋高祖纪·天福三年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b5136a33bd66e49c58489b48336695f7b1236b9b/content/books/zizhi-tongjian/vol-281/year-0938/part-01/sources/library/jiuwudaishi-077-january/source.txt", "note": "《旧五代史》卷77·晋高祖纪·天福三年正月，段落 jiu-wudaishi-205deb4a7860-p001911；已核上下文及传主，纸本及异文待核。", "id": "d9b6ac0f-0f41-5f86-9070-e5caad2179ea"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/184c40b49cc874d45b3c000680968fee2ef8f443/content/books/zizhi-tongjian/vol-281/year-0937/part-07/sources/library/tongjian-281-937-min-and-year-end/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003344；电子底本待考，分段待核", "id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"title": "新五代史·卷62·南唐世家", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/184c40b49cc874d45b3c000680968fee2ef8f443/content/books/zizhi-tongjian/vol-281/year-0937/part-07/sources/library/xinwudaishi-062-accession/source.txt", "note": "《新五代史》卷62·南唐世家，段落 xin-wudaishi-b08f244b9241-p003128；已核上下文及传主，纸本及异文待核。", "id": "fa6cfc9d-507c-5fa2-9e84-890a60000798"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "周本", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：周本。", "biography": null, "status": "draft", "id": "88dc9c09-49c3-51ee-b872-381abedabdf2"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "张业", "aliases": ["張業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张业。", "biography": null, "status": "draft", "id": "79f0f8ee-f0c7-5ba0-a428-aacf648664be"}, {"name": "王处回", "aliases": ["王處回"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王处回，为税官请免的中门副使。", "biography": null, "status": "draft", "id": "159fd2b3-759b-522a-a971-11356c6fe970"}, {"name": "张允", "aliases": ["張允"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋左散骑常侍。938年二月庚辰向石敬瑭提交《驳赦论》，质疑以大赦消除天灾的做法，得到诏书褒奖。", "biography": null, "status": "draft", "id": "832a2405-9822-5a07-a561-b0b86dee97c8"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "梁文矩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。石敬瑭命他与另外九人设立详定院，审核百官提交的密封奏章，具体设院年月未载。", "biography": null, "status": "draft", "id": "b9cb20fe-9c64-5530-a79e-6ef844ac4e4c"}, {"name": "李详（后晋中书舍人）", "aliases": ["李详", "李詳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋中书舍人。938年上疏批评地方荐官过多、名位混乱，提出限制荐官范围和人数，石敬瑭采纳了建议。", "biography": null, "status": "draft", "id": "1854d752-9202-59a9-9c41-b882e294d4cb"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "《资治通鉴》记正月己酉发生日食", "start_year": 938, "end_year": 938, "time_original": "938年正月己酉", "dynasty": "五代十国", "description": "《资治通鉴》记正月己酉发生日食。《旧五代史》同日记太史先奏日食，但届时“不亏”，两书记载不同。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7ea4645e-2625-5856-b4ed-96044abc398f"}, {"title": "周本因未能保全吴国而惭愧怨恨，随后去世", "start_year": 938, "end_year": 938, "time_original": "938年正月，具体日期未记载", "dynasty": "五代十国", "description": "周本因未能保全吴国而惭愧怨恨，随后去世。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3dbaa145-d04a-546e-95b8-27dfcf50d860"}, {"title": "徐景遂被任命参判尚书都省", "start_year": 938, "end_year": 938, "time_original": "938年正月丙寅", "dynasty": "五代十国", "description": "徐景遂被任命参判尚书都省。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cfb663ad-3cb9-52f7-9e24-0f0ed2dbad01"}, {"title": "孟昶任命张业为左仆射等职并兼枢密使", "start_year": 938, "end_year": 938, "time_original": "938年正月，具体日期未记载", "dynasty": "五代十国", "description": "孟昶任命张业为左仆射等职并兼枢密使。", "phases": [], "location_name": "蜀国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "45a9bff9-4cb5-5e47-a883-072b9343d003"}, {"title": "王处回兼任武信节度使、同平章事", "start_year": 938, "end_year": 938, "time_original": "938年正月，具体日期未记载", "dynasty": "五代十国", "description": "王处回兼任武信节度使、同平章事。", "phases": [], "location_name": "蜀国、武泰军与武信军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4b83fc36-388c-5001-a647-b3f6f6cf65b0"}, {"title": "张允提交《驳赦论》，质疑用大赦消除天灾", "start_year": 938, "end_year": 938, "time_original": "938年二月庚辰", "dynasty": "五代十国", "description": "张允提交《驳赦论》，认为大赦可能让有罪者幸免、使受害者含冤，因此未必能够消除天灾。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "70e34a46-de57-5b00-8879-628474b4eaec"}, {"title": "石敬瑭下诏褒奖张允", "start_year": 938, "end_year": 938, "time_original": "938年二月庚辰条下", "dynasty": "五代十国", "description": "石敬瑭下诏褒奖张允。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3a41adb0-66c8-5172-ba49-bce12b29ca34"}, {"title": "石敬瑭要求百官各提交密封奏章", "start_year": null, "end_year": null, "time_original": "《资治通鉴》二月条后概述，求封事原诏确切年月未明", "dynasty": "五代十国", "description": "石敬瑭愿意听取直言，要求百官各提交密封奏章。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "641937a4-e651-5360-baf7-04bf33ef7945"}, {"title": "石敬瑭命梁文矩等十人设详定院，审核奏章", "start_year": null, "end_year": null, "time_original": "求百官封事的安排，具体设院年月未明", "dynasty": "五代十国", "description": "石敬瑭命梁文矩等十人设立详定院，审核百官奏章；没有可采用意见的留在宫中，有可采用意见的实行。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c6624ce6-dff7-521d-b3d2-c04514610acd"}, {"title": "百官上书者不足十人，石敬瑭再次亲笔诏书催促", "start_year": null, "end_year": null, "time_original": "求百官封事诏后数月的乙未，确切年月未明", "dynasty": "五代十国", "description": "数月后，应诏上书的人仍不足十人。石敬瑭在乙未再次发出亲笔诏书催促。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4a79077f-1cc2-5120-9407-3215b3a0555b"}, {"title": "石敬瑭禁止民间制作铜器", "start_year": 938, "end_year": 938, "time_original": "938年三月丁丑", "dynasty": "五代十国", "description": "石敬瑭禁止民间制作铜器。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8e4f5076-6e76-5d3e-8986-b0daad23607a"}, {"title": "战乱后铸钱作坊废弃，铜钱逐渐减少", "start_year": null, "end_year": null, "time_original": "唐代以来及战乱后的背景，起止年份未载", "dynasty": "五代十国", "description": "《资治通鉴》追述唐代曾有三十六处铸钱作坊，战乱以来这些作坊全部废弃，铜钱日益减少。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dc7c4b96-01d6-58b7-beb5-f2a644af9086"}, {"title": "民间熔化铜钱制成铜器，朝廷因此下禁令", "start_year": null, "end_year": null, "time_original": "938年三月禁制铜器之前，现象持续起止未载", "dynasty": "五代十国", "description": "民间多有熔化铜钱制作铜器的情况，《资治通鉴》将它列为朝廷下禁令的原因。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dfe1a95f-e724-5449-8413-adcebaa42d75"}, {"title": "李详建议限制地方荐官范围和人数", "start_year": 938, "end_year": 938, "time_original": "938年三月，具体日期未记载", "dynasty": "五代十国", "description": "李详批评地方荐官过多，连吏员、优伶、奴仆初次受任也可能得到高阶和服饰。他建议在领兵将校之外，节度州只许推荐硃记大将以上十人，其他州只许推荐都押牙、都虞候、孔目官；其余由本道调整职名。石敬瑭采纳了建议。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2573efd3-e0e9-5bde-a33c-3482a5439a96"}, {"title": "宋齐丘要求参与政务，徐诰以省署未备作答", "start_year": 938, "end_year": 938, "time_original": "938年四月甲申", "dynasty": "五代十国", "description": "宋齐丘认为自己身为丞相，不应被排除在政务之外。徐诰回答说省署尚未完备。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1ef981bb-05da-53b5-adc6-c07b89a02aac"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

