SELECT id, person_id, event_id, role, status FROM jsonb_populate_recordset(NULL::public.person_event, '[{"role": "在南唐任德胜节度使兼中书令，以未能保全吴国为憾而去世", "status": "draft", "id": "2811269d-69ad-5434-8ac9-bb9a7180008d", "person_id": "88dc9c09-49c3-51ee-b872-381abedabdf2", "event_id": "3dbaa145-d04a-546e-95b8-27dfcf50d860"}, {"role": "任命侍中、吉王徐景遂参判尚书都省", "status": "draft", "id": "2f2b9d7b-52e4-5aab-af3f-e90acb6c00b5", "person_id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9", "event_id": "cfb663ad-3cb9-52f7-9e24-0f0ed2dbad01"}, {"role": "被任命参与主持尚书都省事务", "status": "draft", "id": "79843d78-61db-5d07-b37b-c4c171f666a9", "person_id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13", "event_id": "cfb663ad-3cb9-52f7-9e24-0f0ed2dbad01"}, {"role": "任命张业为左仆射兼中书侍郎、同平章事、枢密使", "status": "draft", "id": "8a191f00-5996-5789-b8ce-711dc4d87fe1", "person_id": "666201f7-9186-590e-8d5b-2a4a605dba69", "event_id": "45a9bff9-4cb5-5e47-a883-072b9343d003"}, {"role": "由武信节度使、同平章事获任左仆射等职并兼枢密使", "status": "draft", "id": "a1ff6f07-2d5f-558f-9520-9f054a0e7951", "person_id": "79f0f8ee-f0c7-5ba0-a428-aacf648664be", "event_id": "45a9bff9-4cb5-5e47-a883-072b9343d003"}, {"role": "让王处回兼任武信节度使、同平章事", "status": "draft", "id": "b6fe58a5-d019-51da-8256-e258f5c933c3", "person_id": "666201f7-9186-590e-8d5b-2a4a605dba69", "event_id": "4b83fc36-388c-5001-a647-b3f6f6cf65b0"}, {"role": "在任武泰节度使的基础上兼武信节度使、同平章事", "status": "draft", "id": "b7219473-bdc7-51f6-9803-c43537b0e186", "person_id": "159fd2b3-759b-522a-a971-11356c6fe970", "event_id": "4b83fc36-388c-5001-a647-b3f6f6cf65b0"}, {"role": "以左散骑常侍身份提交《驳赦论》", "status": "draft", "id": "80ba6888-8564-5ee1-a350-ecb87bc7ff43", "person_id": "832a2405-9822-5a07-a561-b0b86dee97c8", "event_id": "70e34a46-de57-5b00-8879-628474b4eaec"}, {"role": "收到张允关于大赦与天灾的议论", "status": "draft", "id": "47639957-ab7e-503b-b08f-98142a31be83", "person_id": "bf42d98c-7477-5be1-a767-867fe26cf617", "event_id": "70e34a46-de57-5b00-8879-628474b4eaec"}, {"role": "对张允的《驳赦论》下诏褒奖", "status": "draft", "id": "2dbf9cd0-9602-52ce-95