INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "《资治通鉴》记正月己酉发生日食。《旧五代史》同日记太史先奏日食，但届时“不亏”，两书记载不同。", "citation": "卷281·后晋天福三年（938；正月条下）·zztj-v281-y0938-p001·原文件第67行", "note": "原文：春，正月，己酉，日有食之。；核对说明：只录史载，不据电子本计算天文食分或现代公历日期。", "status": "draft", "id": "c95668b2-22da-5a9c-a166-4a70c65abdf7", "subject_id": "7ea4645e-2625-5856-b4ed-96044abc398f", "source_id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "938年正月己酉", "citation": "卷281·后晋天福三年（938；正月条下）·zztj-v281-y0938-p001·原文件第67行", "note": "原文：春，正月，己酉，日有食之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "40ea7b40-013f-52ff-a7e4-4bbc2b334a1e", "subject_id": "7ea4645e-2625-5856-b4ed-96044abc398f", "source_id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》记正月己酉因太史先预报日食，百官守在官署，但届时不亏，朝内外称贺。", "citation": "《旧五代史》卷77·晋高祖纪·天福三年正月，段落 jiu-wudaishi-205deb4a7860-p001911；已核上下文及传主，纸本及异文待核。", "note": "原文：己酉，百官守司，以太史先奏日蝕故也。至是不虧，內外稱賀。；核对说明：不亏与《资治通鉴》有食不同，作为独立异说；不把预报直接等同实际观测。", "status": "draft", "id": "bc30798d-4722-53da-811d-4cfda0455ec6", "subject_id": "7ea4645e-2625-5856-b4ed-96044abc398f", "source_id": "d9b6ac0f-0f41-5f86-9070-e5caad2179ea"}, {"subject_table": "event", "field_path": "description", "claim_text": "周本因未能保全吴国而惭愧怨恨，随后去世。", "citation": "卷281·后晋天福三年（938；正月条下）·zztj-v281-y0938-p002·原文件第68行", "note": "原文：唐德胜节度使兼中书令西平恭烈王周本以不能存吴，愧恨而卒。；核对说明：以不能存吴愧恨为史书所述心情和原因，不另作医学死因。西平恭烈王是史书称谓，不据此补当日封爵或谥号日期。", "status": "draft", "id": "61084fce-a760-5c68-8bd4-eb9c7edd77fc", "subject_id": "3dbaa145-d04a-546e-95b8-27dfcf50d860", "source_id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "938年正月，具体日期未记载", "citation": "卷281·后晋天福三年（938；正月条下）·zztj-v281-y0938-p002·原文件第68行", "note": "原文：唐德胜节度使兼中书令西平恭烈王周本以不能存吴，愧恨而卒。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "b7fc073b-e301-5aa2-98eb-a854230fbc7c", "subject_id": "3dbaa145-d04a-546e-95b8-27dfcf50d860", "source_id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"subject_table": "person", "field_path": "description", "claim_text": "周本：在南唐任德胜节度使兼中书令，以未能保全吴国为憾而去世。", "citation": "卷281·后晋天福三年（938；正月条下）·zztj-v281-y0938-p002·原文件第68行", "note": "原文：唐德胜节度使兼中书令西平恭烈王周本以不能存吴，愧恨而卒。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "6e143234-b2f4-5fd4-9e62-7a2da87388c1", "subject_id": "88dc9c09-49c3-51ee-b872-381abedabdf2", "source_id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "周本：在南唐任德胜节度使兼中书令，以未能保全吴国为憾而去世。", "citation": "卷281·后晋天福三年（938；正月条下）·zztj-v281-y0938-p002·原文件第68行", "note": "原文：唐德胜节度使兼中书令西平恭烈王周本以不能存吴，愧恨而卒。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "989f8e30-3f9a-551d-8a05-52554a560acc", "subject_id": "2811269d-69ad-5434-8ac9-bb9a7180008d", "source_id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》记周本劝进后自责未能报答杨氏，愤恨而死。", "citation": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003128；EPUB电子本，纸本及异文待核", "note": "原文：周本與諸將至金陵勸進，歸而嘆曰：「吾不誅篡國者以報楊氏，今老矣，豈能事二姓乎！」憤惋而死。；核对说明：该书把死亡与受禅后感慨相接，没有独列正月死日；不因此硬定他在937年十月已经死亡。", "status": "draft", "id": "ca4bf333-63e5-571a-be3d-fe4dbbb64444", "subject_id": "3dbaa145-d04a-546e-95b8-27dfcf50d860", "source_id": "fa6cfc9d-507c-5fa2-9e84-890a60000798"}, {"subject_table": "person", "field_path": "death_year", "claim_text": "《资治通鉴》将周本去世列于938年正月条下。", "citation": "卷281·后晋天福三年（938；正月条下）·zztj-v281-y0938-p002·原文件第68行", "note": "原文：唐德胜节度使兼中书令西平恭烈王周本以不能存吴，愧恨而卒。；核对说明：据主书所在年份补死亡事实，具体日未载；已有主体和旧档案不覆写。", "status": "draft", "id": "88553d56-0a0d-5539-9850-54a1fa2d39d6", "subject_id": "88dc9c09-49c3-51ee-b872-381abedabdf2", "source_id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"subject_table